/* Fluxo da fábrica por obra. Dados antigos permanecem no mesmo registro. */
(function(root){
'use strict';
const D=root.Obras,M=root.EngefexFactoryModel,clone=D.clone;
const stages=[['cut','Corte'],['drill','Furação'],['assembly','Montagem'],['weld','Soldagem'],['finish','Acabamento'],['paint','Pintura']];
const readyTemplate=[['Projeto','Projeto e revisão de fabricação conferidos'],['Materiais','Perfis, chapas e componentes separados e identificados'],['Materiais','Materiais conferidos com a lista de peças'],['Produção','Medidas e detalhes de ligação compreendidos pela equipe'],['Produção','Ferramentas, equipamentos e área de trabalho disponíveis'],['Equipe','Responsáveis e sequência de fabricação definidos']];
const qualityTemplate=[['Identificação','Peças e marcas correspondem ao projeto de fabricação'],['Quantidade','Todas as peças previstas foram produzidas e contadas'],['Dimensões','Dimensões, cortes e furações conferidos'],['Montagem','Posições, alinhamento e encaixes conferidos'],['Soldagem','Soldas conferidas conforme os critérios do projeto'],['Acabamento','Rebarbas, respingos e superfícies conferidos'],['Proteção','Pintura ou tratamento de superfície conferidos'],['Pendências','Correções de fabricação encerradas e registradas']];
function checks(rows){return rows.map(([group,name])=>({id:M.id(),group,name,status:'pending',owner:'',note:''}))}
function createFlow(){return {version:1,profile:{structureType:'',scope:'',drawing:'',steel:'',coating:'painted',color:'',width:'',length:'',height:'',notes:''},routes:{},events:[],ready:checks(readyTemplate),quality:checks(qualityTemplate),closedAt:'',closedBy:'',reopenReason:''}}
function ensure(order){let o=clone(order);if(!o.workflow)o.workflow=createFlow();return o}
function fresh(project){let o=M.fresh(project.id);o.number=project.code||'FABRICA';o.fields=[];o.preparation=[];o.shipping=[];o.workflow=createFlow();return o}
function route(o,p){return o.workflow?.routes?.[p.id]||['cut','assembly','weld','finish',...(o.workflow?.profile?.coating==='painted'?['paint']:[])]}
function legacy(o,p){let t=M.totals(o,p.id);return {fabricated:t.fabricated,painted:t.painted,prepared:t.prepared,released:t.released}}
function total(o,p,stage){let b=legacy(o,p),base=stage==='paint'?b.painted:b.fabricated;return base+D.sum((o.workflow?.events||[]).filter(e=>e.part===p.id&&e.stage===stage),e=>M.num(e.quantity))}
function previous(o,p,stage){let list=route(o,p),i=list.indexOf(stage);return i===0?M.num(p.planned):i>0?total(o,p,list[i-1]):0}
function available(o,p,stage){return Math.max(0,Math.min(M.num(p.planned),previous(o,p,stage))-total(o,p,stage))}
function complete(o,p){return M.num(p.planned)>0&&route(o,p).every(stage=>total(o,p,stage)>=M.num(p.planned)-1e-8)}
function checkDone(c){return c.status==='ok'||c.status==='na'&&!!String(c.note||'').trim()}
function profileIssues(o){let w=o.workflow,p=w.profile,out=[];if(!String(o.owner||'').trim())out.push('Defina o responsável pela fabricação.');if(!p.structureType.trim())out.push('Informe o tipo de estrutura.');if(!p.scope.trim())out.push('Descreva o escopo de fabricação.');if(!p.drawing.trim())out.push('Informe a referência do projeto de fabricação.');if(!p.steel.trim())out.push('Informe os materiais / aços previstos.');return out}
function closureIssues(o){let w=o.workflow,issues=profileIssues(o);if(!o.parts.some(p=>M.num(p.planned)>0))issues.push('Cadastre pelo menos uma peça com quantidade prevista.');if(w.ready.some(c=>!checkDone(c)))issues.push('Conclua o checklist de preparação.');if(o.parts.some(p=>M.num(p.planned)>0&&!complete(o,p)))issues.push('Conclua as etapas previstas de todas as peças.');if(w.quality.some(c=>!checkDone(c)))issues.push('Conclua o checklist final de fabricação.');if(w.quality.some(c=>checkDone(c)&&!String(c.owner||'').trim()))issues.push('Informe quem conferiu cada item do checklist final.');return issues}
function validate(o){let w=o.workflow;if(!w)return true;if(w.version!==1||!w.profile||!w.routes||typeof w.routes!=='object'||Array.isArray(w.routes))throw Error('Dados do fluxo da fábrica inválidos.');for(let key of ['structureType','scope','drawing','steel','coating','color','width','length','height','notes'])if(typeof w.profile[key]!=='string')throw Error('Caracterização da fábrica inválida.');if(!['painted','galvanized','none'].includes(w.profile.coating))throw Error('Escolha o tratamento de superfície.');if(!Array.isArray(w.events)||w.events.length>20000)throw Error('Registros de produção inválidos.');let ids=new Set();for(let e of w.events){if(!e.id||ids.has(e.id)||!o.parts.some(p=>p.id===e.part)||!stages.some(([s])=>s===e.stage)||M.num(e.quantity)<=0||!e.date||!D.date(e.date)||D.date(e.date).toLocaleDateString('sv-SE')!==e.date||!String(e.owner||'').trim())throw Error('Revise peça, etapa, quantidade, data e responsável do lançamento.');ids.add(e.id)}for(let p of o.parts){let list=route(o,p);if(!Array.isArray(list)||!list.length||new Set(list).size!==list.length||list.some(s=>!stages.some(([k])=>k===s))||list.join()!==stages.filter(([k])=>list.includes(k)).map(([k])=>k).join())throw Error('Defina a sequência de fabricação da peça '+p.name+'.');let old=legacy(o,p);for(let [stage] of stages){let additions=D.sum(w.events.filter(e=>e.part===p.id&&e.stage===stage),e=>M.num(e.quantity));if(additions>0&&!list.includes(stage))throw Error(p.name+': há lançamentos nesta etapa. Corrija os registros antes de retirar a etapa.');if(additions>0&&(total(o,p,stage)>M.num(p.planned)+1e-8||total(o,p,stage)>previous(o,p,stage)+1e-8))throw Error(p.name+': a quantidade supera o previsto ou o disponível na etapa anterior.');if(!Number.isFinite(old.fabricated))throw Error('Saldo anterior inválido.')}}for(let key of ['ready','quality']){if(!Array.isArray(w[key])||!w[key].length||w[key].length>500)throw Error('Checklist da fábrica inválido.');let checkIds=new Set();for(let c of w[key]){if(!c.id||checkIds.has(c.id)||!String(c.name||'').trim()||!['pending','ok','issue','na'].includes(c.status)||typeof c.note!=='string'||typeof c.owner!=='string')throw Error('Revise o checklist da fábrica.');checkIds.add(c.id);if(['issue','na'].includes(c.status)&&!c.note.trim())throw Error('Registre uma observação para a pendência ou para o item não aplicável.')}}if(typeof w.closedAt!=='string'||w.closedAt&&!Number.isFinite(Date.parse(w.closedAt)))throw Error('Data de encerramento inválida.');if(w.closedAt&&(!w.closedBy?.trim()||closureIssues(o).length))throw Error('A fabricação encerrada precisa estar completa e conferida.');return true}
function resetQuality(o){for(let c of o.workflow.quality){c.status='pending';c.owner='';c.checkedAt=''}return o}
function record(order,input){let o=ensure(order),w=o.workflow;if(w.closedAt)throw Error('Reabra a fabricação antes de lançar.');let missing=profileIssues(o);if(missing.length)throw Error(missing[0]);if(w.ready.some(c=>!checkDone(c)))throw Error('Conclua a preparação antes de registrar produção.');let p=o.parts.find(p=>p.id===input.part);if(!p||!route(o,p).includes(input.stage))throw Error('Selecione uma peça e uma etapa prevista.');let quantity=M.num(input.quantity);if(!quantity)throw Error('Informe uma quantidade maior que zero.');if(quantity>available(o,p,input.stage)+1e-8)throw Error('Quantidade maior que o saldo disponível nesta etapa.');resetQuality(o);w.events.push({id:M.id(),part:p.id,stage:input.stage,quantity,date:input.date,owner:String(input.owner||'').trim(),note:String(input.note||'').trim()});validate(o);return o}
function removeEvent(order,eventId){let o=ensure(order);if(o.workflow.closedAt)throw Error('Reabra a fabricação antes de corrigir registros.');if(!o.workflow.events.some(e=>e.id===eventId))throw Error('Lançamento não encontrado.');o.workflow.events=o.workflow.events.filter(e=>e.id!==eventId);resetQuality(o);try{validate(o)}catch{throw Error('Há etapas posteriores usando esta quantidade. Corrija primeiro os lançamentos posteriores.')}return o}
function close(order,owner){let o=ensure(order),issues=closureIssues(o);if(issues.length)throw Error(issues.join(' '));if(!String(owner||'').trim())throw Error('Informe o responsável pelo encerramento.');o.workflow.closedAt=new Date().toISOString();o.workflow.closedBy=owner.trim();validate(o);return o}
function reopen(order,reason){let o=ensure(order);if(!reason?.trim())throw Error('Informe o motivo da reabertura.');o.workflow.closedAt='';o.workflow.closedBy='';o.workflow.reopenReason=reason.trim();resetQuality(o);return o}
function parseParts(text){let lines=String(text||'').replace(/^\uFEFF/,'').replace(/\r/g,'').split('\n').filter(l=>l.trim());if(!lines.length)throw Error('Cole a lista de peças.');let delimiter=lines[0].includes('\t')?'\t':';';let rows=lines.map(l=>l.split(delimiter).map(v=>v.trim()));if(/^(marca|c[oó]digo|marca\s*\/\s*c[oó]digo)$/i.test(rows[0][0]))rows.shift();if(!rows.length)throw Error('A lista contém somente o cabeçalho.');return rows.map((cells,i)=>{if(cells.length<5||cells.length>7)throw Error('Linha '+(i+1)+': use as colunas Marca, Nome, Grupo, Unidade, Quantidade, Perfil / dimensões e Observações.');let [code,name,group,unit,planned,dimensions='',note='']=cells;if(!name)throw Error('Linha '+(i+1)+': informe o nome da peça.');if(!planned)throw Error('Linha '+(i+1)+': informe a quantidade prevista.');return {code,name,group,unit:unit||'un',planned:M.num(planned),dimensions,note}})}
function appendParts(order,rows,settings={}){let o=ensure(order);if(o.workflow.closedAt)throw Error('Reabra a fabricação antes de cadastrar peças.');if(!rows.length)throw Error('Nenhuma peça para incluir.');let codes=new Set(o.parts.map(p=>p.code.trim().toLocaleLowerCase('pt-BR')).filter(Boolean));for(let row of rows){let p={...M.part(),...clone(row),id:M.id()};p.name=String(p.name||'').trim();p.unit=String(settings.unit||p.unit||'un').trim();p.group=String(settings.group||p.group||'').trim();p.planned=M.num(p.planned);if(!p.name)throw Error('Informe o nome de cada peça.');p.code=String(p.code||'').trim();if(!p.code){let n=o.parts.length+1;do{p.code='P'+String(n++).padStart(2,'0')}while(codes.has(p.code.toLocaleLowerCase('pt-BR')))}let code=p.code.toLocaleLowerCase('pt-BR');if(codes.has(code))throw Error('Marca repetida: '+p.code+'. Use marcas diferentes ou ajuste o item já cadastrado.');codes.add(code);o.parts.push(p);o.workflow.routes[p.id]=settings.stages?clone(settings.stages):['cut','assembly','weld','finish',...(o.workflow.profile.coating==='painted'?['paint']:[])]}if(o.parts.length>5000)throw Error('A lista ultrapassa 5.000 peças.');resetQuality(o);validate(o);return o}
function bulkParts(order,ids,settings){let o=ensure(order);if(o.workflow.closedAt)throw Error('Reabra a fabricação antes de editar peças.');if(!settings.group?.trim()&&!settings.unit&&!settings.stages)throw Error('Informe o grupo, a unidade ou as operações para aplicar.');if(!ids.length||ids.some(id=>!o.parts.some(p=>p.id===id)))throw Error('Selecione as peças que deseja alterar.');for(let p of o.parts.filter(p=>ids.includes(p.id))){if(settings.group)p.group=settings.group.trim();if(settings.unit&&settings.unit.trim()!==p.unit){if(o.workflow.events.some(e=>e.part===p.id)||legacy(o,p).fabricated||legacy(o,p).painted)throw Error('Não altere a unidade de uma peça com produção registrada.');p.unit=settings.unit.trim();}if(settings.stages)o.workflow.routes[p.id]=clone(settings.stages)}resetQuality(o);validate(o);return o}

function pasteGrid(order,start,key,text){let o=ensure(order),keys=['code','name','group','unit','planned','dimensions','note'],column=keys.indexOf(key);if(column<0||start<0||start>o.parts.length)throw Error('Célula de destino inválida.');let lines=String(text).replace(/\r/g,'').replace(/\n$/,'').split('\n').map(l=>l.split('\t'));if(start+lines.length>5000)throw Error('A colagem ultrapassa 5.000 peças.');for(let [ri,values]of lines.entries()){if(values.length+column>keys.length)throw Error('A colagem ultrapassa as colunas da grade.');while(o.parts.length<=start+ri){let p=M.part();o.parts.push(p);o.workflow.routes[p.id]=['cut','assembly','weld','finish',...(o.workflow.profile.coating==='painted'?['paint']:[])]}for(let [ci,value]of values.entries())o.parts[start+ri][keys[column+ci]]=keys[column+ci]==='planned'?M.num(value):value.trim()}resetQuality(o);return o}
root.EngefexFactoryFlow={pasteGrid,parseParts,appendParts,bulkParts,stages,resetQuality,ensure,fresh,route,legacy,total,previous,available,complete,checkDone,profileIssues,closureIssues,validate,record,removeEvent,close,reopen};
})(typeof window==='undefined'?globalThis:window);
